        Object call(String name,Object... arguments)throws Exception{Class<?>[] classes=new Class<?>[arguments.length];for(int i=0;i<arguments.length;i++){Object value=arguments[i];classes[i]=value instanceof Long?long.class:value instanceof Integer?int.class:value instanceof Double?double.class:value instanceof Boolean?boolean.class:value instanceof Float?float.class:value.getClass();}try{return type.getMethod(name,classes).invoke(object,arguments);}catch(InvocationTargetException e){if(e.getCause() instanceof Exception cause)throw cause;if(e.getCause() instanceof Error cause)throw cause;throw e;}}
