    private static void originalRotor()throws Exception{for(int facing=0;facing<4;facing++){var old=new Old(120,8,true,facing);var orientation=ClassicWindRules.Facing.values()[facing];float modern=0;long last=-1;for(long now:new long[]{1000,1100,1500,6000,6020}){String[] operations=(String[])old.call("render",now);check(Arrays.asList(operations).contains("mesh:windgen_fan"),"unchanged original renderer draws fan");check(Arrays.asList(operations).contains("translate:"+cn.academy.port.client.ClassicWindVisualRules.pivotX(ClassicWindRules.Kind.MAIN,orientation)+",0.0,"+cn.academy.port.client.ClassicWindVisualRules.pivotZ(ClassicWindRules.Kind.MAIN,orientation)),"full original BlockMulti renderer pivot");check(Arrays.asList(operations).contains("rotate:"+cn.academy.port.client.ClassicWindVisualRules.yaw(orientation)+",0.0,1.0,0.0"),"full original orientation angle");modern=cn.academy.port.client.ClassicWindVisualRules.rotation(modern,60,last==-1?0:now-last);last=now;equal(old.number("rotation"),modern,"unchanged original rotor dt/float accumulation");}var obstacle=ClassicWindRules.obstaclePlane(orientation).getFirst();old.call("obstacle",obstacle.x(),obstacle.y(),obstacle.z());var hidden=(String[])old.call("render",7000L);check(!Arrays.asList(hidden).contains("mesh:windgen_fan"),"original obstacle completely hides fan");equal(old.number("rotation"),modern,"hidden fan does not advance animation");old.call("removeObstacle",obstacle.x(),obstacle.y(),obstacle.z());old.call("render",10000L);modern=cn.academy.port.client.ClassicWindVisualRules.rotation(modern,60,10000-last);equal(old.number("rotation"),modern,"original hidden interval catches up on reappearance");}}
